const $=(s,r=document)=>r.querySelector(s);const $$=(s,r=document)=>Array.from(r.querySelectorAll(s));
const uid=()=>((window.crypto&&typeof window.crypto.randomUUID==='function')?window.crypto.randomUUID():`id-${Date.now()}-${Math.random().toString(16).slice(2)}`);
const euro=n=>new Intl.NumberFormat(undefined,{style:'currency',currency:'EUR'}).format(Number(n||0));
const euro3=n=>new Intl.NumberFormat(undefined,{style:'currency',currency:'EUR',minimumFractionDigits:3,maximumFractionDigits:3}).format(Number(n||0));
const num=(n,d=1)=>Number(n||0).toLocaleString(undefined,{maximumFractionDigits:d});
const esc=s=>String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateLabel=s=>s?new Date(s).toLocaleDateString(undefined,{day:'2-digit',month:'short',year:'numeric'}):'—';
function formObject(form){const out={};new FormData(form).forEach((v,k)=>{out[k]=v});return out}
function readFileText(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result||''));r.onerror=()=>reject(r.error||new Error('Could not read file'));r.readAsText(file)})}

let state={route:'dashboard',vehicles:[],fillups:[],promos:[],settings:{},editing:null,prefill:null,priceResults:[],deferredPrompt:null,userPos:null,searchCenter:null,priceCountry:null,priceMeta:null,priceFuels:[],cardToggles:{}};
let priceMap=null;
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200)}
function appDialog(opts){const root=$('#modalRoot'),title=$('#modalTitle'),body=$('#modalBody'),ok=$('#modalConfirm'),cancel=$('#modalCancel');if(!root)return Promise.resolve(false);title.textContent=opts.title||'';body.textContent=opts.body||'';ok.textContent=opts.confirmLabel||'OK';ok.className='btn'+(opts.danger?' danger':'');const showCancel=opts.cancelLabel!==null;cancel.classList.toggle('hidden',!showCancel);if(showCancel)cancel.textContent=opts.cancelLabel||'Cancel';root.classList.remove('hidden');root.setAttribute('aria-hidden','false');ok.focus();return new Promise(resolve=>{const finish=v=>{root.classList.add('hidden');root.setAttribute('aria-hidden','true');root.removeEventListener('click',onClick);document.removeEventListener('keydown',onKey);resolve(v)};const onClick=e=>{if(e.target===ok)finish(true);else if(e.target===cancel||(e.target&&e.target.hasAttribute&&e.target.hasAttribute('data-modal-cancel')))finish(false)};const onKey=e=>{if(e.key==='Escape'&&showCancel)finish(false)};root.addEventListener('click',onClick);document.addEventListener('keydown',onKey)})}
async function setting(key,fallback=null){const r=await FuelDB.get('settings',key);return r&&r.value!==undefined?r.value:fallback}
async function setSetting(key,value){await FuelDB.put('settings',{key,value});state.settings[key]=value}
async function refresh(){state.vehicles=await FuelDB.all('vehicles');state.fillups=(await FuelDB.all('fillups')).sort((a,b)=>new Date(b.date)-new Date(a.date));state.promos=(await FuelDB.all('promos'))||[];for(const k of ['activeVehicle','fuelTypeId','lastBackup','priceCountry','promoFillLitres','suggestBtn','mapView','priceSheetSnap','cacheMapTiles','mapOnlineProvider'])state.settings[k]=await setting(k,null)}
function mapOnlineProviderId(){const d=window.FuelLogOfflineTiles&&FuelLogOfflineTiles.defaultProvider||'opentopomap';return state.settings.mapOnlineProvider||d}
function mapProviderOptionsHtml(selected){const list=window.FuelLogOfflineTiles?FuelLogOfflineTiles.listProviders():[{id:'opentopomap',label:'Terrain (OpenTopoMap)'}];return list.map(p=>`<option value="${esc(p.id)}" ${p.id===selected?'selected':''}>${esc(p.label)}</option>`).join('')}
function syncMapProviderControl(){const sel=$('#mapOnlineProvider');if(!sel)return;const off=!navigator.onLine;sel.disabled=off;sel.title=off?'Offline — bundled terrain map only':'Map style while online'}
function activeVehicle(){return state.vehicles.find(v=>v.id===state.settings.activeVehicle)||state.vehicles[0]||null}
function vehicleFillups(id){return state.fillups.filter(f=>f.vehicleId===id).sort((a,b)=>new Date(a.date)-new Date(b.date))}
function calcMetrics(v){const fs=vehicleFillups(v&&v.id);if(!fs.length)return{distance:0,litres:0,cost:0,avg:null,costKm:null,last:null};const last=fs[fs.length-1],distance=Math.max(0,(last&&last.odometer||0)-(fs[0]&&fs[0].odometer||0)),litres=fs.reduce((s,f)=>s+Number(f.litres||0),0),cost=fs.reduce((s,f)=>s+Number(f.totalCost||0),0);let fullDistance=0,fullLitres=0,lastFull=null,acc=0;for(const f of fs){acc+=Number(f.litres||0);if(f.fullTank){if(lastFull){fullDistance+=Number(f.odometer)-Number(lastFull.odometer);fullLitres+=acc}lastFull=f;acc=0}}return{distance,litres,cost,avg:fullDistance>0?fullLitres/fullDistance*100:null,costKm:distance>0?cost/distance:null,last:last}}
function consumptionSeries(vehicleId){const fs=vehicleFillups(vehicleId),out=[];let lastFull=null,acc=0;for(const f of fs){acc+=Number(f.litres||0);if(f.fullTank){if(lastFull){const dist=Number(f.odometer)-Number(lastFull.odometer);if(dist>0)out.push({t:new Date(f.date).getTime(),y:acc/dist*100})}lastFull=f;acc=0}}return out}
function priceSeries(vehicleId){return vehicleFillups(vehicleId).map(f=>{const y=Number(f.pricePerLitre!=null?f.pricePerLitre:(f.litres?f.totalCost/f.litres:NaN));return{t:new Date(f.date).getTime(),y}}).filter(p=>isFinite(p.y)&&p.y>0)}
function sparklineSvg(points,opts){opts=opts||{};if(!points||points.length<2)return'';const w=320,h=160,pad=28;const xs=points.map(p=>p.t),ys=points.map(p=>p.y);const minX=Math.min.apply(null,xs),maxX=Math.max.apply(null,xs);const minY=Math.min.apply(null,ys),maxY=Math.max.apply(null,ys);const spanX=maxX-minX||1,spanY=maxY-minY||1;const coord=p=>({x:pad+(p.t-minX)/spanX*(w-2*pad),y:h-pad-(p.y-minY)/spanY*(h-2*pad)});const pts=points.map(coord);const line=pts.map((p,i)=>(i?'L':'M')+p.x.toFixed(1)+','+p.y.toFixed(1)).join(' ');const area=line+' L'+pts[pts.length-1].x.toFixed(1)+','+(h-pad)+' L'+pts[0].x.toFixed(1)+','+(h-pad)+' Z';const cls=opts.accent?'chart chart-accent':'chart';const yLo=minY.toFixed(2),yHi=maxY.toFixed(2);const d0=dateLabel(new Date(minX).toISOString()),d1=dateLabel(new Date(maxX).toISOString());return `<svg class="${cls}" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(opts.yLabel||'Chart')}"><path class="gridline" d="M${pad} ${pad} H${w-pad}"/><path class="gridline" d="M${pad} ${h-pad} H${w-pad}"/><path class="area" d="${area}"/><path class="line" d="${line}"/><text x="${pad}" y="14">${yHi}</text><text x="${pad}" y="${h-6}">${yLo}</text><text x="${pad}" y="${h-pad+14}">${esc(d0)}</text><text x="${w-pad}" y="${h-pad+14}" text-anchor="end">${esc(d1)}</text></svg>`}
function analysisCard(vehicleId){const cons=consumptionSeries(vehicleId),price=priceSeries(vehicleId);const consHtml=cons.length>=2?`<div class="chart-block"><h3>L/100 km</h3>${sparklineSvg(cons,{yLabel:'L/100 km'})}</div>`:`<div class="chart-block"><h3>L/100 km</h3><p class="muted">Need at least two full-tank fill-ups for consumption.</p></div>`;const priceHtml=price.length>=2?`<div class="chart-block"><h3>€/L</h3>${sparklineSvg(price,{accent:true,yLabel:'€/L'})}</div>`:`<div class="chart-block"><h3>€/L</h3><p class="muted">Need at least two fill-ups with price for €/L.</p></div>`;return `<div class="card"><h2>Fill analysis</h2>${consHtml}${priceHtml}</div>`}
function route(name){state.route=name;state.editing=null;$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.route===name));render()}
const ROUTE_LABEL={dashboard:'Home',add:'Fill-up',history:'History',prices:'Prices',settings:'Settings'};
function updateSuggestBtn(){const b=$('#suggestBtn');if(!b)return;const hidden=state.settings.suggestBtn===false;b.classList.toggle('hidden',hidden);if(!hidden)b.href='mailto:nuno.f.pedrosa@gmail.com?subject='+encodeURIComponent('[Fuel suggestion]')+'&body='+encodeURIComponent('Page: '+(pageTitle()||state.route)+'\n\nSuggestion: ')}
function wrap(body){return body}
function pageTitle(){if(state.route==='add'&&state.editing&&state.editing.id)return 'Edit fill-up';return ROUTE_LABEL[state.route]||''}
function fillRow(f){const v=state.vehicles.find(x=>x.id===f.vehicleId);return `<div class="row"><div><strong>${dateLabel(f.date)}</strong><div class="muted">${esc(v&&v.name||'Vehicle')} ${f.station?'· '+esc(f.station):''}</div></div><div><strong>${num(f.odometer,0)} km</strong><div class="muted">odometer</div></div><div><strong>${num(f.litres,2)} L</strong><div class="muted">${f.fullTank?'full tank':'partial'}</div></div><div><strong>${euro(f.totalCost)}</strong><div class="muted">${f.pricePerLitre?euro3(f.pricePerLitre)+'/L':''}</div></div><div class="actions-inline"><button class="icon-btn" data-edit="${f.id}">✎</button><button class="icon-btn danger-link" data-delete="${f.id}">×</button></div></div>`}
function dashboard(){const v=activeVehicle();if(!v)return `<div class="empty">Add a vehicle in Settings to begin.</div>`;const m=calcMetrics(v),recent=state.fillups.filter(f=>f.vehicleId===v.id).slice(0,5);return `<div class="hero"><div class="hero-card"><h1>${esc(v.name)}</h1><p>${[v.make,v.model,v.registration].filter(Boolean).map(esc).join(' · ')}</p><div class="hero-metric">${m.avg?num(m.avg,2):'—'} <small>L/100 km average</small></div></div><div class="side-card"><div><div class="kicker">Latest fill-up</div><div class="big">${m.last?euro(m.last.totalCost):'No entries'}</div><p class="muted">${m.last?`${num(m.last.litres,2)} L · ${dateLabel(m.last.date)}`:'Add your first fill-up.'}</p></div><button class="btn" data-route="add">+ Add fill-up</button></div></div><div class="grid"><div class="stat"><div class="label">Distance logged</div><div class="value">${num(m.distance,0)} km</div></div><div class="stat"><div class="label">Fuel logged</div><div class="value">${num(m.litres,1)} L</div></div><div class="stat"><div class="label">Total spend</div><div class="value">${euro(m.cost)}</div></div><div class="stat"><div class="label">Cost / km</div><div class="value">${m.costKm?euro(m.costKm):'—'}</div></div></div>${analysisCard(v.id)}<div class="section-head"><h2>Recent fill-ups</h2><button class="btn secondary" data-route="history">View all</button></div>${recent.length?`<div class="list">${recent.map(fillRow).join('')}</div>`:`<div class="empty">No fill-ups yet.</div>`}`}
function fillForm(){const v=activeVehicle(),f=Object.assign({},state.editing||{},state.prefill||{});state.prefill=null;const now=new Date(),local=new Date(now.getTime()-now.getTimezoneOffset()*60000).toISOString().slice(0,16);return `<div class="card form-card"><form id="fillForm"><input type="hidden" name="stationId" value="${esc(f.stationId||'')}"><input type="hidden" name="country" value="${esc(f.country||'')}"><input type="hidden" name="fuelId" value="${esc(f.fuelId||'')}"><div class="form-grid"><div class="field"><label>Vehicle</label><select name="vehicleId" required>${state.vehicles.map(x=>`<option value="${x.id}" ${(f.vehicleId||(v&&v.id))===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Date & time</label><input type="datetime-local" name="date" value="${(f.date||local).slice(0,16)}" required></div><div class="field"><label>Odometer (km)</label><input type="number" step="1" min="0" name="odometer" value="${f.odometer!=null?f.odometer:''}" required></div><div class="field"><label>Litres</label><input type="number" step="0.001" min="0" name="litres" value="${f.litres!=null?f.litres:''}" required></div><div class="field"><label>Total cost (€)</label><input type="number" step="0.01" min="0" name="totalCost" value="${f.totalCost!=null?f.totalCost:''}" required></div><div class="field"><label>Price / litre (€)</label><input type="number" step="0.001" min="0" name="pricePerLitre" value="${f.pricePerLitre!=null?f.pricePerLitre:''}"></div><div class="field"><label>Station</label><input name="station" value="${esc(f.station||'')}" placeholder="Optional"></div><div class="field"><label>Fuel type</label><input name="fuelType" value="${esc(f.fuelType||(v&&v.fuelType)||'')}" placeholder="Gasóleo simples"></div><div class="switchline"><input type="checkbox" name="fullTank" ${f.fullTank!==false?'checked':''}><label>Full tank</label></div><div class="field full"><label>Notes</label><textarea name="notes">${esc(f.notes||'')}</textarea></div></div><div class="form-actions"><button type="button" class="btn ghost" data-route="history">Cancel</button><button class="btn">${f.id?'Update fill-up':'Save fill-up'}</button></div></form></div>`}
function history(){return `<div class="toolbar"><select id="historyVehicle"><option value="all">All vehicles</option>${state.vehicles.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select><input id="historySearch" placeholder="Search station or notes"></div><div class="section-head"><h2>${state.fillups.length} fill-ups</h2><button class="btn" data-route="add">+ Add fill-up</button></div><div id="historyList" class="list">${state.fillups.length?state.fillups.map(fillRow).join(''):`<div class="empty">No fill-ups yet.</div>`}</div>`}
function proxyUrl(){return (window.FUELLOG_CONFIG&&window.FUELLOG_CONFIG.stationProxy)||null}
const round3=n=>Math.round(n*1000)/1000;
async function searchProxy(dataset,fuel,center,radiusKm){const r=await fetch(new URL(proxyUrl(),location.href),{method:'POST',headers:{'Content-Type':'application/json'},credentials:'omit',cache:'no-store',body:JSON.stringify({provider:dataset,fuel:String(fuel),lat:round3(center.lat),lon:round3(center.lon),radius:radiusKm})});if(!r.ok)throw new Error('Proxy returned '+r.status);return r.json()}
function defaultPriceCountry(){const l=((navigator.languages&&navigator.languages[0])||navigator.language||'').toUpperCase(),m=l.match(/-([A-Z]{2})/),code=m?m[1]:l;return FuelProviders.countries().some(c=>c.code===code)?code:'PT'}
function countryFlag(code){const c=String(code||'').toUpperCase();if(c.length!==2)return c;const base=0x1F1E6,a=base+c.charCodeAt(0)-65,b=base+c.charCodeAt(1)-65;if(String.fromCodePoint)return String.fromCodePoint(a,b);return String.fromCharCode(55296+(a-0x10000>>10),56320+(a-0x10000&1023))+String.fromCharCode(55296+(b-0x10000>>10),56320+(b-0x10000&1023))}
function priceCountryOptionsHtml(selected){return FuelProviders.countries().map(c=>`<option value="${c.code}" ${c.code===selected?'selected':''} title="${esc(c.name)}">${countryFlag(c.code)}</option>`).join('')}
function syncPriceCountrySelectLabel(){const sel=$('#priceCountry');if(!sel)return;const c=(FuelProviders.countries().filter(x=>x.code===sel.value)[0]||{});sel.title=c.name||'Country';sel.setAttribute('aria-label',c.name?'Country: '+c.name:'Country')}
function priceProvider(){const cc=state.priceCountry||defaultPriceCountry();return FuelProviders.stationProvider(cc)||FuelProviders.referenceProvider(cc)}
const COUNTRY_VIEW={PT:[39.6,-8.0,6],ES:[40.2,-3.7,6],FR:[46.6,2.4,6],BE:[50.6,4.6,8],NL:[52.2,5.3,7]};
const LISBON_MAP={lat:38.7223,lon:-9.1393,zoom:12};
function defaultMapView(){return{lat:LISBON_MAP.lat,lon:LISBON_MAP.lon,zoom:LISBON_MAP.zoom}}
function savedMapView(){const v=state.settings.mapView;return v&&Number.isFinite(+v.lat)&&Number.isFinite(+v.lon)?{lat:+v.lat,lon:+v.lon,zoom:Number.isFinite(+v.zoom)?+v.zoom:LISBON_MAP.zoom}:null}
function mapViewCenter(){const v=savedMapView();return v||defaultMapView()}
let mapViewSaveTimer=null;
function persistMapView(map){const m=map||(priceMap&&priceMap.map);if(!m)return;const c=m.getCenter();setSetting('mapView',{lat:round3(c.lat),lon:round3(c.lon),zoom:m.getZoom()}).catch(console.error)}
function scheduleMapViewSave(map){clearTimeout(mapViewSaveTimer);mapViewSaveTimer=setTimeout(()=>persistMapView(map),400)}
const PRICE_TYPE_LABEL={station:'current station price','official-maximum':'official maximum','national-average':'national average'};
function provLabel(s){if(!s.provenance)return'';const p=FuelProviders.byId(s.provenance.sourceId);return[(p&&p.name)||s.provenance.sourceId,PRICE_TYPE_LABEL[s.provenance.priceType]||s.provenance.priceType].filter(Boolean).join(' · ')}
function proxyStation(provider,s,fuel,sourceUpdatedAt,retrievedAt){return{id:provider.id+':'+s.id,country:provider.country,name:s.name,brand:s.brand,address:s.address,town:s.town,updated:s.updated||'',lat:s.lat,lon:s.lon,price:s.price,unit:(provider.units&&provider.units[fuel])||'litre',distance:s.distance,provenance:{sourceType:provider.sourceType,sourceId:provider.id,priceType:provider.priceType,sourceUpdatedAt:FuelProviders.localIso(s.updated)||sourceUpdatedAt||null,retrievedAt:retrievedAt}}}
const PRICE_ARCHIVE_TTL=7*864e5,PRICE_ARCHIVE_MAX=20,PRICE_ARCHIVE_STATIONS_MAX=500;
function normalizePriceSheetSnap(snap){return snap==='peek'||snap==='half'?snap:'half'}
function priceSheetSnap(){return normalizePriceSheetSnap(state.settings.priceSheetSnap||'peek')}
function prices(){const cc=state.priceCountry=state.settings.priceCountry||defaultPriceCountry(),provider=priceProvider(),isRef=!!(provider&&!provider.capabilities.stationPrices),proxyOn=!!(proxyUrl()&&provider&&provider.proxyDataset),showRegion=!!(provider&&provider.capabilities.regions&&!proxyOn),locNotice=isRef?'Official reference prices for the whole country. No location is sent anywhere.':proxyOn?'Find stations uses the map centre (rounded to about 100 m), sent only to this site\'s own station service and never stored. Tap ◎ on the map to ask for your location and centre the map.':'Find stations uses the map centre for the area you are viewing. Choose a region when required. Tap ◎ on the map to ask for your location and centre the map.',emptyMsg=isRef?'Loading official prices…':'Choose a fuel, pan the map if needed, then Find stations.',snap=priceSheetSnap();return `<div class="price-map-layout"><div class="price-map-stage map-wrap"><div id="stationMap"></div><div class="price-map-tools"><select id="mapOnlineProvider" class="map-provider-select" aria-label="Map style when online">${mapProviderOptionsHtml(mapOnlineProviderId())}</select></div><div id="priceOfflineBanner" class="price-offline-banner hidden" role="status"></div></div><div id="priceSheet" class="price-sheet" data-snap="${esc(snap)}"><button type="button" id="priceSheetHandle" class="price-sheet-handle" aria-expanded="${snap!=='peek'}" aria-controls="priceSheetScroll"><span class="price-sheet-grab"></span></button><div class="price-sheet-peek"><div class="price-filters toolbar price-filters-peek"><select id="priceCountry" class="price-country-select" aria-label="Country">${priceCountryOptionsHtml(cc)}</select><select id="priceFuel" aria-label="Fuel"><option>Loading fuels…</option></select><select id="radius" class="${isRef?' hidden':''}" aria-label="Search radius"><option value="2">2 km</option><option value="5">5 km</option><option value="10" selected>10 km</option><option value="20">20 km</option><option value="50">50 km</option><option value="150">150 km</option><option value="300">300 km</option><option value="1000">1000 km</option></select><button id="findPrices" class="btn price-find-btn">${isRef?'Update':'Find'}</button></div><button type="button" id="priceSummaryPeek" class="price-summary-peek muted">Results appear here after you search</button></div><div id="priceSheetScroll" class="price-sheet-scroll"><div class="price-filters toolbar price-filters-full"><div class="filter-field${showRegion?'':' hidden'}" id="regionField"><select id="priceRegion" aria-label="Region"><option value="">Loading regions…</option></select></div></div><div id="priceSummary" class="price-summary hidden"></div><div id="priceOfflineNotice" class="notice hidden"></div><div id="stationList" class="list price-station-list"><div class="empty">${emptyMsg}</div></div>${userHistoryHtml(cc)}<details class="price-source-details"><summary>Source & privacy</summary><p class="muted">${locNotice}</p>${provider?`<p class="muted">Source: <a href="${esc(provider.sourceUrl)}" target="_blank" rel="noopener">${esc(provider.name)}</a> · ${esc(provider.license||'')}</p>`:''}<div class="notice">Public price data may lag the pump. Always confirm the price at the station.</div></details></div></div></div>`}
function userStationPrices(s){const n=FuelProviders.norm,name=n(s.name),brandTown=n([s.brand,s.town].filter(Boolean).join(' '));return state.fillups.filter(f=>f.stationId?f.stationId===s.id:(f.station&&(n(f.station)===name||n(f.station)===brandTown))).sort((a,b)=>new Date(b.date)-new Date(a.date)).map(f=>({date:f.date,price:f.pricePerLitre||f.totalCost/f.litres}))}
function userHistoryHtml(cc){const n=FuelProviders.norm,def=state.priceCountry||defaultPriceCountry(),groups={};state.fillups.forEach(f=>{if(!(f.country===cc||(!f.country&&cc===def)))return;const name=String(f.station||'').trim(),key=f.stationId||n(name);if(!key)return;(groups[key]=groups[key]||{name:name||key,rows:[]}).rows.push(f)});const gs=Object.keys(groups).map(k=>groups[k]);gs.forEach(g=>g.rows.sort((a,b)=>new Date(b.date)-new Date(a.date)));gs.sort((a,b)=>new Date(b.rows[0].date)-new Date(a.rows[0].date));if(!gs.length)return'';return `<div class="section-head"><h2>Your history</h2></div><div class="list">${gs.slice(0,8).map(g=>`<div class="station"><div><h3>${esc(g.name)}</h3><div class="meta">Your history · ${g.rows.length} fill-ups</div></div><div>${g.rows.slice(0,3).map(f=>`<div>${dateLabel(f.date)} — ${euro3(f.pricePerLitre||f.totalCost/f.litres)}/L</div>`).join('')}</div></div>`).join('')}</div>`}
function youPaidHtml(s){const h=userStationPrices(s);return h.length?`<div class="meta you-paid">You paid ${euro3(h[0].price)}/L here · ${FuelProviders.ago(h[0].date)}</div>`:''}
function promoFillLitres(){const v=+state.settings.promoFillLitres;return v>0?v:FuelLogPromos.DEFAULT_FILL_LITRES}
function currentFuelCanonical(){const meta=state.priceMeta||{},fu=(state.priceFuels||[]).find(x=>String(x.key)===String(meta.fuelKey));return(fu&&fu.canonical)||null}
function fuelUnit(s){return s.unit&&s.unit!=='litre'?s.unit:'L'}
function stationOffer(s){return s._offer||FuelLogPromos.offers(s,currentFuelCanonical(),state.promos,promoFillLitres())}
function stationSortPrice(s){const offer=stationOffer(s),w=offer.winner;if(w&&Number.isFinite(w.price))return w.price;if(offer.base!=null&&Number.isFinite(offer.base))return offer.base;return Number.isFinite(s.price)?s.price:NaN}
function priceTierClass(s,minPrice){const p=stationSortPrice(s);if(!Number.isFinite(p)||!Number.isFinite(minPrice))return'';const d=p-minPrice;if(d<=0.01)return'price-tier-best';if(d<0.05)return'price-tier-mid';return'price-tier-high'}
function priceTierMarkerStyle(s,minPrice){const tier=priceTierClass(s,minPrice);if(tier==='price-tier-best')return{color:'#15803d',fillColor:'#86efac'};if(tier==='price-tier-mid')return{color:'#a16207',fillColor:'#fde047'};if(tier==='price-tier-high')return{color:'#b91c1c',fillColor:'#f87171'};return{color:'#0f766e',fillColor:'#14b8a6'}}
