function settingsPage(){const av=activeVehicle();return `<div class="settings-grid"><div class="card"><div class="section-head"><h2>Vehicles</h2><button id="addVehicle" class="btn secondary">+ Vehicle</button></div><div id="vehicles">${state.vehicles.length?state.vehicles.map(v=>`<div class="vehicle-card"><div><strong>${esc(v.name)}</strong><div class="muted">${[v.make,v.model,v.registration,v.preferredFuel?FuelLogFuels.label(v.preferredFuel):''].filter(Boolean).map(esc).join(' · ')}</div></div><div class="actions-inline"><button class="icon-btn" data-vehicle-active="${v.id}">${av&&av.id===v.id?'★':'☆'}</button><button class="icon-btn" data-vehicle-edit="${v.id}">✎</button><button class="icon-btn danger-link" data-vehicle-delete="${v.id}">×</button></div></div>`).join(''):`<div class="empty">Add your first vehicle.</div>`}</div></div><div class="card"><div class="section-head"><h2>Brand promos</h2><button id="addPromo" class="btn secondary">+ Promo</button></div><div id="promos">${(state.promos||[]).length?state.promos.slice().sort((a,b)=>String(a.brand).localeCompare(String(b.brand))).map(promoRow).join(''):`<div class="empty">No promos yet.</div>`}</div><div class="field"><label>Typical fill (L) — used to compare per-fill discounts</label><input id="promoFillLitres" type="number" step="1" min="1" value="${promoFillLitres()}"></div><p class="muted">Promos match the station's brand exactly (accents and case ignored). Cumulative promos stack. An exclusive promo is compared with that stack, and stations are sorted by the better effective price.</p></div><div class="card"><h2>Backup & portability</h2><p class="muted">Full JSON backup is the safest format. Import also accepts generic JSON, CSV, semicolon CSV, TSV and delimited TXT files.</p><div class="actions-stack"><button id="exportJson" class="btn">Export JSON backup</button><button id="exportCsv" class="btn secondary">Export fill-ups CSV</button><label class="btn ghost">Import data<input id="importData" type="file" accept=".json,.csv,.tsv,.txt,application/json,text/csv,text/tab-separated-values,text/plain" hidden></label></div><p class="muted">Imports recognise common English and Portuguese headings such as date/data, odometer/quilometragem, litres/litros, cost/custo and station/posto. Decimal commas are supported.</p><p class="muted">Last backup: ${state.settings.lastBackup?dateLabel(state.settings.lastBackup):'never'}</p></div><div class="card"><h2>Feedback</h2><div class="switchline tight"><input type="checkbox" id="suggestEnabled" ${state.settings.suggestBtn===false?'':'checked'}><label for="suggestEnabled">Show the floating ✉ suggestion button (top right)</label></div><p class="muted">Opens your email app with a pre-addressed suggestion message that names the page you were on. Nothing is sent until you press send.</p></div></div><div class="section-head"><h2>Privacy</h2></div><div class="card"><p><strong>Your log stays on this device.</strong> Vehicles, fill-ups, notes and settings are stored in IndexedDB. FuelLog has no application database on the server.</p><p class="muted">Clearing browser/site storage can erase local records, so keep periodic JSON backups. On older iPhones, exporting a backup before clearing Safari data is especially important.</p></div>`}
function promoDesc(p){const bits=[p.country||'Any country',p.type==='fill'?'-'+euro(p.amount)+' per fill':'-'+euro3(p.amount)+'/L',p.fuelId?FuelLogFuels.label(p.fuelId):'any fuel',p.cumulative===false?'exclusive':'cumulative'];if(p.validUntil)bits.push((FuelLogPromos.active(p)?'until ':'expired ')+dateLabel(p.validUntil+'T00:00:00'));if(p.notes)bits.push(p.notes);return bits.map(esc).join(' · ')}
function promoRow(p){return `<div class="vehicle-card"><div><strong>${esc(p.brand)}</strong><div class="muted">${promoDesc(p)}</div></div><div class="actions-inline"><button class="icon-btn" data-promo-edit="${p.id}">✎</button><button class="icon-btn danger-link" data-promo-delete="${p.id}">×</button></div></div>`}
function promoDialog(p={}){return `<div class="card form-card"><form id="promoForm"><input type="hidden" name="id" value="${p.id||''}"><div class="form-grid"><div class="field"><label>Brand</label><input name="brand" required value="${esc(p.brand||'')}" placeholder="Galp"></div><div class="field"><label>Country</label><select name="country"><option value="">Any country</option>${FuelProviders.countries().map(c=>`<option value="${c.code}" ${p.country===c.code?'selected':''}>${c.name}</option>`).join('')}</select></div><div class="field"><label>Discount type</label><select name="type"><option value="litre" ${p.type!=='fill'?'selected':''}>€ per litre off</option><option value="fill" ${p.type==='fill'?'selected':''}>€ per fill off</option></select></div><div class="field"><label>Amount (€)</label><input name="amount" type="number" step="0.001" min="0" required value="${p.amount!=null?p.amount:''}"></div><div class="field"><label>Fuel</label><select name="fuelId"><option value="">Any fuel</option>${FuelLogFuels.LIST.map(x=>`<option value="${x.id}" ${p.fuelId===x.id?'selected':''}>${x.label}</option>`).join('')}</select></div><div class="field"><label>Valid until</label><input name="validUntil" type="date" value="${esc(p.validUntil||'')}"></div><div class="field full"><div class="switchline"><input type="checkbox" name="cumulative" id="promoCumulative" ${p.cumulative!==false?'checked':''}><label for="promoCumulative">Cumulative</label></div><p class="muted">Stacks with other cumulative promos. Turn off if this promo cannot be combined.</p></div><div class="field full"><label>Notes</label><input name="notes" value="${esc(p.notes||'')}" placeholder="Optional"></div></div><div class="form-actions"><button type="button" id="promoCancel" class="btn ghost">Cancel</button><button class="btn">Save promo</button></div></form></div>`}
function wirePromoForm(){const f=$('#promoForm');$('#promoCancel').onclick=()=>render();f.onsubmit=async e=>{e.preventDefault();const d=formObject(f),old=(state.promos||[]).find(x=>x.id===d.id)||{};await FuelDB.put('promos',{...old,id:d.id||uid(),brand:d.brand.trim(),country:d.country||'',type:d.type==='fill'?'fill':'litre',amount:+d.amount||0,fuelId:d.fuelId||'',validUntil:d.validUntil||'',notes:d.notes.trim(),active:true,cumulative:d.cumulative==='on',updatedAt:new Date().toISOString()});await refresh();render();toast('Promo saved')}}
function vehicleDialog(v={}){return `<div class="card form-card"><form id="vehicleForm"><input type="hidden" name="id" value="${v.id||''}"><div class="form-grid"><div class="field"><label>Name</label><input name="name" required value="${esc(v.name||'')}" placeholder="My car"></div><div class="field"><label>Registration</label><input name="registration" value="${esc(v.registration||'')}"></div><div class="field"><label>Make</label><input name="make" value="${esc(v.make||'')}"></div><div class="field"><label>Model</label><input name="model" value="${esc(v.model||'')}"></div><div class="field"><label>Preferred fuel</label><select name="preferredFuel"><option value="">Not set</option>${FuelLogFuels.LIST.map(x=>`<option value="${x.id}" ${v.preferredFuel===x.id?'selected':''}>${x.label}</option>`).join('')}</select></div><div class="field"><label>Fuel label (as shown at the pump)</label><input name="fuelType" value="${esc(v.fuelType||'Gasóleo simples')}"></div><div class="field"><label>Initial odometer</label><input type="number" name="initialOdometer" value="${v.initialOdometer||''}"></div></div><div class="form-actions"><button type="button" id="vehicleCancel" class="btn ghost">Cancel</button><button class="btn">Save vehicle</button></div></form></div>`}
function render(){const app=$('#app');state.pageKicker=null;if(state.route==='dashboard')app.innerHTML=dashboard();if(state.route==='add')app.innerHTML=fillForm();if(state.route==='history')app.innerHTML=history();if(state.route==='prices'){app.innerHTML=prices();wirePrices()}if(state.route==='settings')app.innerHTML=settingsPage();syncPricesRoute();wireCommon();updateSuggestBtn();wireCardToggles();const title=pageTitle();const pk=$('#pageKicker');if(pk)pk.textContent=title;document.title='FuelLog'+(title?' · '+title:'')}
function wireCardToggles(){$$('#app .card,#app .side-card,#app .hero-card').forEach((c,i)=>{let head=null;Array.prototype.slice.call(c.children).forEach(ch=>{if(!head&&(ch.classList.contains('section-head')||/^(H1|H2|H3)$/.test(ch.tagName)))head=ch});if(head)head.classList.add('card-keep');const key=state.route+':'+i,b=document.createElement('button');b.type='button';b.className='card-collapse';const apply=off=>{c.classList.toggle('collapsed',off);b.textContent=off?'+':'–';b.title=off?'Open':'Collapse';b.setAttribute('aria-expanded',off?'false':'true')};apply(!!state.cardToggles[key]);b.onclick=()=>{const off=!c.classList.contains('collapsed');apply(off);state.cardToggles[key]=off};c.appendChild(b)})}
function wireCommon(){$$('[data-route]').forEach(b=>b.onclick=()=>route(b.dataset.route));$$('[data-edit]').forEach(b=>b.onclick=()=>{state.editing=state.fillups.find(f=>f.id===b.dataset.edit);state.route='add';render()});$$('[data-delete]').forEach(b=>b.onclick=async()=>{if(!await appDialog({title:'Delete fill-up',body:'Delete this fill-up? This cannot be undone.',confirmLabel:'Delete',danger:true}))return;await FuelDB.del('fillups',b.dataset.delete);await refresh();render();toast('Fill-up deleted')});
const ff=$('#fillForm');if(ff){const L=ff.litres,C=ff.totalCost,P=ff.pricePerLitre;const sync=source=>{if(source!=='price'&&+L.value>0&&+C.value>0)P.value=(+C.value/+L.value).toFixed(3);if(source==='price'&&+L.value>0&&+P.value>0)C.value=(+L.value*+P.value).toFixed(2)};L.oninput=()=>sync('litres');C.oninput=()=>sync('cost');P.oninput=()=>sync('price');ff.onsubmit=async e=>{e.preventDefault();const d=formObject(ff);const old=state.editing||{};const sv=state.vehicles.find(x=>x.id===d.vehicleId);await FuelDB.put('fillups',{...old,id:old.id||uid(),vehicleId:d.vehicleId,date:new Date(d.date).toISOString(),odometer:+d.odometer,litres:+d.litres,totalCost:+d.totalCost,pricePerLitre:d.pricePerLitre?+d.pricePerLitre:(+d.totalCost/+d.litres),station:d.station.trim(),stationId:d.stationId||null,country:d.stationId?(d.country||state.priceCountry||defaultPriceCountry()):null,fuelId:d.fuelId||FuelLogFuels.guess(d.fuelType)||(sv&&sv.preferredFuel)||null,fuelType:d.fuelType.trim(),fullTank:ff.fullTank.checked,notes:d.notes.trim(),updatedAt:new Date().toISOString()});await refresh();route('dashboard');toast('Fill-up saved')}}
const hv=$('#historyVehicle'),hs=$('#historySearch');const filterHistory=()=>{if(!$('#historyList'))return;let fs=state.fillups;const vid=(hv&&hv.value)||'all',q=((hs&&hs.value)||'').toLowerCase();if(vid!=='all')fs=fs.filter(f=>f.vehicleId===vid);if(q)fs=fs.filter(f=>`${f.station} ${f.notes} ${f.fuelType}`.toLowerCase().includes(q));$('#historyList').innerHTML=fs.length?fs.map(fillRow).join(''):`<div class="empty">No matching fill-ups.</div>`;$$('[data-edit]').forEach(b=>b.onclick=()=>{state.editing=state.fillups.find(f=>f.id===b.dataset.edit);state.route='add';render()});$$('[data-delete]').forEach(b=>b.onclick=async()=>{if(!await appDialog({title:'Delete fill-up',body:'Delete this fill-up? This cannot be undone.',confirmLabel:'Delete',danger:true}))return;await FuelDB.del('fillups',b.dataset.delete);await refresh();render();toast('Fill-up deleted')})};if(hv)hv.onchange=filterHistory;if(hs)hs.oninput=filterHistory;
if($('#addVehicle'))$('#addVehicle').onclick=()=>{$('#vehicles').innerHTML=vehicleDialog();wireVehicleForm()};$$('[data-vehicle-edit]').forEach(b=>b.onclick=()=>{$('#vehicles').innerHTML=vehicleDialog(state.vehicles.find(v=>v.id===b.dataset.vehicleEdit));wireVehicleForm()});$$('[data-vehicle-active]').forEach(b=>b.onclick=async()=>{await setSetting('activeVehicle',b.dataset.vehicleActive);render()});$$('[data-vehicle-delete]').forEach(b=>b.onclick=async()=>{const id=b.dataset.vehicleDelete;if(state.fillups.some(f=>f.vehicleId===id)){await appDialog({title:'Cannot delete',body:'Delete this vehicle’s fill-ups first.',confirmLabel:'OK',cancelLabel:null});return}if(!await appDialog({title:'Delete vehicle',body:'Delete this vehicle?',confirmLabel:'Delete',danger:true}))return;await FuelDB.del('vehicles',id);if(state.settings.activeVehicle===id)await setSetting('activeVehicle',null);await refresh();render()});if($('#addPromo'))$('#addPromo').onclick=()=>{$('#promos').innerHTML=promoDialog();wirePromoForm()};$$('[data-promo-edit]').forEach(b=>b.onclick=()=>{$('#promos').innerHTML=promoDialog((state.promos||[]).find(p=>p.id===b.dataset.promoEdit));wirePromoForm()});$$('[data-promo-delete]').forEach(b=>b.onclick=async()=>{if(!await appDialog({title:'Delete promo',body:'Delete this promo?',confirmLabel:'Delete',danger:true}))return;await FuelDB.del('promos',b.dataset.promoDelete);await refresh();render()});const pfl=$('#promoFillLitres');if(pfl)pfl.onchange=async()=>{await setSetting('promoFillLitres',+pfl.value||FuelLogPromos.DEFAULT_FILL_LITRES)};const sg=$('#suggestEnabled');if(sg)sg.onchange=async()=>{await setSetting('suggestBtn',sg.checked);updateSuggestBtn();toast(sg.checked?'Suggestion button shown':'Suggestion button hidden')};if($('#exportJson'))$('#exportJson').onclick=exportJson;if($('#exportCsv'))$('#exportCsv').onclick=exportCsv;if($('#importData'))$('#importData').onchange=importData}
function wireVehicleForm(){const f=$('#vehicleForm');$('#vehicleCancel').onclick=()=>render();f.onsubmit=async e=>{e.preventDefault();const d=formObject(f);const rec={id:d.id||uid(),name:d.name.trim(),registration:d.registration.trim(),make:d.make.trim(),model:d.model.trim(),fuelType:d.fuelType.trim(),preferredFuel:d.preferredFuel||FuelLogFuels.guess(d.fuelType)||null,initialOdometer:+d.initialOdometer||0};await FuelDB.put('vehicles',rec);if(!activeVehicle())await setSetting('activeVehicle',rec.id);await refresh();render();toast('Vehicle saved')}}
async function wirePrices(){priceMap=null;const cc=state.priceCountry=state.settings.priceCountry||defaultPriceCountry(),provider=priceProvider(),isRef=!!(provider&&!provider.capabilities.stationPrices),sel=$('#priceFuel'),regionSel=$('#priceRegion'),proxyOn=!!(proxyUrl()&&provider&&provider.proxyDataset);const savedFuel=await setting('priceFuel:'+cc,null);try{const fuels=await provider.fuels();state.priceFuels=fuels;const av=activeVehicle(),pref=av&&av.preferredFuel;let pick=savedFuel||'';if(!pick&&pref){const f=fuels.filter(x=>x.canonical===pref)[0];if(f)pick=f.key}if(!pick&&pref)FuelLogFuels.related(pref).some(rid=>{const f=fuels.filter(x=>x.canonical===rid)[0];if(f){pick=f.key;return true}return false});if(!pick&&fuels.length)pick=fuels[0].key;sel.innerHTML=`<option value="">Choose fuel…</option>`+fuels.map(t=>`<option value="${esc(t.key)}" ${String(pick)===String(t.key)?'selected':''}>${esc(t.label)}</option>`).join('')}catch(e){sel.innerHTML=`<option value="">Fuel list unavailable</option>`}if(provider&&provider.capabilities.regions)try{const regions=await provider.regions();regionSel.innerHTML=`<option value="">Choose region…</option>`+regions.map(r=>`<option value="${esc(r.id)}">${esc(r.label)}</option>`).join('')}catch(e){regionSel.innerHTML=`<option value="">Region list unavailable</option>`}$('#priceCountry').onchange=async e=>{await setSetting('priceCountry',e.target.value);state.priceCountry=e.target.value;state.priceResults=[];state.searchCenter=null;state.priceMeta=null;render()};syncPriceCountrySelectLabel();wirePriceSheet();ensureMap();updatePriceOfflineUi();const mps=$('#mapOnlineProvider');if(mps)mps.onchange=async()=>{await setSetting('mapOnlineProvider',mps.value);if(priceMap&&priceMap.tileApi&&priceMap.tileApi.setOnlineProvider)priceMap.tileApi.setOnlineProvider(mps.value);toast('Map style updated')};if(await restorePriceSearchFromArchive())renderStations();if(isRef){$('#findPrices').onclick=async()=>{if(sel.value)await setSetting('priceFuel:'+cc,sel.value);runReference({button:$('#findPrices')})};if(!navigator.onLine&&state.priceResults.length)renderStations();else runReference({button:$('#findPrices')})}if(!isRef)$('#findPrices').onclick=async()=>{if(!sel.value)return toast('Choose a fuel type');if(provider.requiresRegion()&&!proxyOn&&!regionSel.value)return void await appDialog({title:'Choose a region',body:'Choose a region first. This keeps the download small enough for reliable use.',confirmLabel:'OK',cancelLabel:null});await setSetting('priceFuel:'+cc,sel.value);runPriceSearch({fuel:sel.value,regionId:regionSel.value||'',radiusKm:+$('#radius').value,button:$('#findPrices'),busyLabel:'Finding stations…',fit:true,label:'',center:priceSearchCenter()})}}
const legacyIOS=()=>FuelProviders.legacyIOS();function download(name,content,type){if(legacyIOS()){const data='data:'+type+','+encodeURIComponent(content);const w=window.open(data,'_blank');if(!w)window.location.href=data;setTimeout(()=>appDialog({title:'Export',body:'On this iPhone, use Safari Share to save or copy the exported '+name+'.',confirmLabel:'OK',cancelLabel:null}),150);return}const a=document.createElement('a');const url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;document.body.appendChild(a);a.click();document.body.removeChild(a);setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function exportJson(){const backup={format:'FuelLog',version:3,exportedAt:new Date().toISOString(),vehicles:state.vehicles,fillups:state.fillups,promos:state.promos||[],settings:Object.entries(state.settings).map(([key,value])=>({key,value}))};download(`fuellog-backup-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify(backup,null,2),'application/json');await setSetting('lastBackup',new Date().toISOString());render();toast('Backup exported')}
function csvCell(v){const s=String(v==null?'':v);return /[",\n]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s}
function exportCsv(){const head=['id','date','vehicle','odometer_km','litres','total_cost_eur','price_per_litre','full_tank','fuel_type','station','fuel_id','station_id','country','notes'],lines=[head.join(',')];for(const f of state.fillups){const v=state.vehicles.find(x=>x.id===f.vehicleId);lines.push([f.id,f.date,(v&&v.name)||'',f.odometer,f.litres,f.totalCost,f.pricePerLitre,f.fullTank,f.fuelType,f.station,f.fuelId,f.stationId,f.country,f.notes].map(csvCell).join(','))}download(`fuellog-${new Date().toISOString().slice(0,10)}.csv`,lines.join('\n'),'text/csv;charset=utf-8');toast('CSV exported')}
function normalHeader(s){return String(s||'').toLowerCase().trim().replace(/[áàãâä]/g,'a').replace(/[éèêë]/g,'e').replace(/[íìîï]/g,'i').replace(/[óòõôö]/g,'o').replace(/[úùûü]/g,'u').replace(/ç/g,'c').replace(/[^a-z0-9]+/g,'_').replace(/^_+|_+$/g,'')}
function rowValue(row,names){const map={};Object.keys(row||{}).forEach(k=>{map[normalHeader(k)]=row[k]});for(const n of names){const k=normalHeader(n);if(map[k]!==undefined&&String(map[k]).trim()!=='')return map[k]}return ''}
function flexNum(v){if(v===null||v===undefined||v==='')return NaN;let s=String(v).trim().replace(/\s/g,'');if(s.indexOf(',')>=0&&s.indexOf('.')>=0){if(s.lastIndexOf(',')>s.lastIndexOf('.'))s=s.replace(/\./g,'').replace(',','.');else s=s.replace(/,/g,'')}else if(s.indexOf(',')>=0)s=s.replace(',','.');s=s.replace(/[^0-9+\-.]/g,'');return parseFloat(s)}
function flexBool(v){const s=String(v==null?'':v).toLowerCase().trim();return ['1','true','yes','y','sim','s','full','cheio'].indexOf(s)>=0}
function flexDate(v){if(v instanceof Date&&!isNaN(v.getTime()))return v.toISOString();const s=String(v||'').trim();if(!s)return null;const m=s.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2,4})(?:[ T](\d{1,2}):(\d{2})(?::(\d{2}))?)?/);if(m){let y=+m[3];if(y<100)y+=2000;const d=new Date(y,+m[2]-1,+m[1],+(m[4]||0),+(m[5]||0),+(m[6]||0));if(!isNaN(d.getTime()))return d.toISOString()}const d=new Date(s);return isNaN(d.getTime())?null:d.toISOString()}
function guessDelimiter(text){const line=(text.split(/\r?\n/).find(x=>x.trim())||'');const choices=['\t',';',','];let best=',',count=-1;choices.forEach(d=>{let c=0,q=false;for(let i=0;i<line.length;i++){if(line[i]==='"')q=!q;else if(!q&&line[i]===d)c++}if(c>count){count=c;best=d}});return best}
function parseDelimited(text,delimiter){const rows=[];let row=[],cell='',q=false;for(let i=0;i<text.length;i++){const ch=text[i];if(q){if(ch==='"'&&text[i+1]==='"'){cell+='"';i++}else if(ch==='"')q=false;else cell+=ch}else if(ch==='"')q=true;else if(ch===delimiter){row.push(cell);cell=''}else if(ch==='\n'){row.push(cell);rows.push(row);row=[];cell=''}else if(ch!=='\r')cell+=ch}row.push(cell);if(row.some(x=>String(x).trim()!==''))rows.push(row);if(rows.length<2)return[];const head=rows.shift().map((h,i)=>String(h||('column_'+(i+1))).trim());return rows.filter(r=>r.some(x=>String(x).trim()!=='')).map(r=>{const o={};head.forEach((h,i)=>o[h]=r[i]===undefined?'':r[i]);return o})}
function extractRowsFromJson(data){if(Array.isArray(data))return data;if(data&&Array.isArray(data.fillups))return data.fillups;if(data&&Array.isArray(data.records))return data.records;if(data&&Array.isArray(data.entries))return data.entries;if(data&&Array.isArray(data.data))return data.data;return[]}
async function ensureVehicleByName(name,fuelType){const clean=String(name||'').trim();if(!clean)return activeVehicle();let v=state.vehicles.find(x=>String(x.name||'').toLowerCase()===clean.toLowerCase());if(v)return v;v={id:uid(),name:clean,registration:'',make:'',model:'',fuelType:String(fuelType||''),initialOdometer:0};await FuelDB.put('vehicles',v);state.vehicles.push(v);return v}
async function importGenericRows(rows,replace){const valid=[],bad=[];for(let i=0;i<rows.length;i++){const r=rows[i]||{};const date=flexDate(rowValue(r,['date','datetime','timestamp','data','data_hora','datahora']));const odometer=flexNum(rowValue(r,['odometer','odometer_km','mileage','km','kms','quilometragem','conta_quilometros']));const litres=flexNum(rowValue(r,['litres','liters','litros','quantity','volume','combustivel_litros']));let total=flexNum(rowValue(r,['total_cost_eur','total_cost','total','cost','amount','custo','custo_total','preco_total','valor']));let price=flexNum(rowValue(r,['price_per_litre','price_per_liter','price_l','unit_price','price','preco_litro','preco_por_litro']));if(!isFinite(total)&&isFinite(price)&&isFinite(litres))total=price*litres;if(!isFinite(price)&&isFinite(total)&&isFinite(litres)&&litres>0)price=total/litres;if(!date||!isFinite(odometer)||!isFinite(litres)||litres<=0||!isFinite(total)){bad.push(i+2);continue}valid.push({raw:r,date,odometer,litres,total,price})}if(!valid.length)throw new Error('No usable fuel records were detected. Check the column headings.');const msg='Detected '+rows.length+' rows: '+valid.length+' usable'+(bad.length?', '+bad.length+' skipped':'')+'.\n\nPress OK to continue importing.';if(!await appDialog({title:'Import rows',body:msg,confirmLabel:'Continue',cancelLabel:'Cancel'}))return 0;if(replace){await FuelDB.clear('fillups');await FuelDB.clear('vehicles');state.vehicles=[];state.fillups=[]}const existing={};state.fillups.forEach(f=>{existing[[f.vehicleId,f.date,Number(f.odometer),Number(f.litres)].join('|')]=1});let count=0;for(const x of valid){const r=x.raw,fuelType=String(rowValue(r,['fuel_type','fuel','combustivel','tipo_combustivel'])||''),fuelIdRaw=String(rowValue(r,['fuel_id','fuelid','combustivel_id'])||'').trim(),stationId=String(rowValue(r,['station_id','stationid'])||'').trim(),countryRaw=String(rowValue(r,['country','pais','país'])||'').trim().toUpperCase(),vehicleName=String(rowValue(r,['vehicle','vehicle_name','car','car_name','viatura','veiculo'])||'').trim();let v=await ensureVehicleByName(vehicleName,fuelType);if(!v){v={id:uid(),name:'Imported vehicle',registration:'',make:'',model:'',fuelType:fuelType,initialOdometer:0};await FuelDB.put('vehicles',v);state.vehicles.push(v)}const key=[v.id,x.date,Number(x.odometer),Number(x.litres)].join('|');if(existing[key])continue;const sourceId=String(rowValue(r,['id','uuid','record_id'])||'').trim();await FuelDB.put('fillups',{id:sourceId||uid(),vehicleId:v.id,date:x.date,odometer:x.odometer,litres:x.litres,totalCost:x.total,pricePerLitre:isFinite(x.price)?x.price:(x.total/x.litres),station:String(rowValue(r,['station','gas_station','fuel_station','posto','posto_abastecimento'])||'').trim(),stationId:stationId||undefined,country:/^[A-Z]{2}$/.test(countryRaw)?countryRaw:undefined,fuelId:FuelLogFuels.LIST.some(x=>x.id===fuelIdRaw)?fuelIdRaw:(FuelLogFuels.guess(fuelType)||undefined),fuelType:fuelType,fullTank:flexBool(rowValue(r,['full_tank','full','tank_full','deposito_cheio','ateste'])),notes:String(rowValue(r,['notes','note','comment','comments','notas','observacoes'])||'').trim(),updatedAt:new Date().toISOString()});existing[key]=1;count++}if(!state.settings.activeVehicle&&state.vehicles.length)await setSetting('activeVehicle',state.vehicles[0].id);return count}
async function importFuelLogBackup(data,replace){if(data.format!=='FuelLog'||!Array.isArray(data.vehicles)||!Array.isArray(data.fillups))throw new Error('Invalid FuelLog backup');if(replace){await FuelDB.clear('vehicles');await FuelDB.clear('fillups');await FuelDB.clear('promos')}for(const v of data.vehicles)await FuelDB.put('vehicles',v);for(const f of data.fillups)await FuelDB.put('fillups',f);for(const p of data.promos||[])await FuelDB.put('promos',p);for(const settingRec of data.settings||[])if(settingRec.key!=='lastBackup')await FuelDB.put('settings',settingRec);return data.fillups.length}
async function migrateMapTileCache(){if((await setting('mapTileProvider',''))==='otm-v1')return;await FuelDB.clear('mapTiles');await setSetting('mapTileProvider','otm-v1')}
async function migrateData(force){if(!force&&(await setting('schemaMigrated',0))>=3){await migrateMapTileCache();return}for(const v of state.vehicles)if(v.preferredFuel===undefined){v.preferredFuel=FuelLogFuels.guess(v.fuelType)||null;await FuelDB.put('vehicles',v)}for(const f of state.fillups)if(f.fuelId===undefined){const v=state.vehicles.find(x=>x.id===f.vehicleId);f.fuelId=FuelLogFuels.guess(f.fuelType)||(v&&v.preferredFuel)||null;await FuelDB.put('fillups',f)}const ftid=await setting('fuelTypeId',null);if(ftid!=null&&(await setting('priceFuel:PT',null))==null)await setSetting('priceFuel:PT',ftid);if(!force)await setSetting('schemaMigrated',3);await migrateMapTileCache()}
async function importData(e){const file=e.target.files&&e.target.files[0];if(!file)return;try{if(file.size>5*1024*1024)throw new Error('For older iPhones, import files are limited to 5 MB. Split a larger history into smaller files.');const text=await readFileText(file);const trimmed=text.replace(/^\uFEFF/,'').trim();if(!trimmed)throw new Error('The selected file is empty.');const lower=String(file.name||'').toLowerCase();let data=null,rows=null,isBackup=false;if(lower.endsWith('.json')||trimmed[0]==='{'||trimmed[0]==='['){data=JSON.parse(trimmed);isBackup=!!(data&&data.format==='FuelLog'&&Array.isArray(data.fillups));if(!isBackup)rows=extractRowsFromJson(data)}else rows=parseDelimited(trimmed,guessDelimiter(trimmed));const replace=await appDialog({title:'Import mode',body:'Replace removes local vehicles and fill-ups first.\nMerge keeps existing data and adds imported rows.',confirmLabel:'Replace',cancelLabel:'Merge'});let count;if(isBackup)count=await importFuelLogBackup(data,replace);else count=await importGenericRows(rows||[],replace);await refresh();await migrateData(true);render();toast('Imported '+count+' fill-ups')}catch(err){await appDialog({title:'Import failed',body:String(err.message||err),confirmLabel:'OK',cancelLabel:null})}finally{e.target.value=''}}
async function init(){await FuelDB.open();if(FuelProviders.legacyIOS())document.documentElement.classList.add('legacy-ios');await refresh();if(!state.vehicles.length){const first={id:uid(),name:'My car',registration:'',make:'',model:'',fuelType:'Gasóleo simples',initialOdometer:0};await FuelDB.put('vehicles',first);await setSetting('activeVehicle',first.id);await refresh()}await migrateData();render();if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(console.error);window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();state.deferredPrompt=e;$('#installBtn').classList.remove('hidden')});$('#installBtn').onclick=async()=>{if(!state.deferredPrompt)return;state.deferredPrompt.prompt();await state.deferredPrompt.userChoice;state.deferredPrompt=null;$('#installBtn').classList.add('hidden')};const status=()=>{$('#offlineBadge').textContent=navigator.onLine?'Online':'Offline ready';if(state.route==='prices')updatePriceOfflineUi()};window.addEventListener('online',status);window.addEventListener('offline',status);status();const onPricesResize=()=>{if(state.route==='prices'&&priceMap&&priceMap.map)setTimeout(()=>priceMap.map.invalidateSize(),250)};window.addEventListener('orientationchange',onPricesResize);window.addEventListener('resize',onPricesResize);$$('[data-route]',document).forEach(b=>b.onclick=()=>route(b.dataset.route))}
init().catch(e=>{$('#app').innerHTML=`<div class="empty">FuelLog could not start: ${esc(e.message)}</div>`;console.error(e)});
